SELECT `event.id` FROM `events` WHERE has(`event.category`, 'process') AND `host.os.type` = 'windows' AND ((`process.command_line` ilike '% -enc%' OR `process.command_line` ilike '% /enc%' OR `process.command_line` ilike '% –enc%' OR `process.command_line` ilike '% —enc%' OR `process.command_line` ilike '% ―enc%'))
